        "C03"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "median",
                "field": "field_0005",
                "alias": "resp_min_median"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "sort",
          "params": {
            "field": "resp_min_median",
            "direction": "desc"
          }
        }
      ]
    }
  ]
